package main

import "fmt"

type Rectangle struct {
	Width  float64
	Height float64
}

func (r *Rectangle) Scale(factor float64) {
	r.Width *= factor
	r.Height *= factor
}

func (r *Rectangle) SetDimensions(w, h float64) {
	r.Width = w
	r.Height = h
}

func (r Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r Rectangle) String() string {
	return fmt.Sprintf("Rectangle(%.1f x %.1f, area=%.1f)",
		r.Width, r.Height, r.Area())
}

type Node struct {
	Value int
	Next  *Node // pointer to next node
}

func buildList(values []int) *Node {
	if len(values) == 0 {
		return nil
	}
	head := &Node{Value: values[0]}
	current := head
	for _, v := range values[1:] {
		current.Next = &Node{Value: v}
		current = current.Next
	}
	return head
}

func printList(head *Node) {
	for n := head; n != nil; n = n.Next {
		if n.Next != nil {
			fmt.Printf("%d -> ", n.Value)
		} else {
			fmt.Printf("%d\n", n.Value)
		}
	}
}

func main() {
	// Pointer to struct with auto-dereference
	rect := &Rectangle{Width: 5, Height: 3}
	fmt.Println(rect)

	rect.Scale(2) // modifies through pointer
	fmt.Println(rect)

	rect.SetDimensions(10, 4)
	fmt.Println(rect)

	// Slice of struct pointers
	rectangles := []*Rectangle{
		{2, 3},
		{4, 5},
		{6, 7},
	}

	totalArea := 0.0
	for _, r := range rectangles {
		r.Scale(1.1) // modifies each rectangle
		totalArea += r.Area()
	}
	fmt.Printf("\nTotal area after scaling: %.2f\n", totalArea)

	// Linked list using pointers
	fmt.Println("\nLinked list:")
	list := buildList([]int{1, 2, 3, 4, 5})
	printList(list)
}
